dashboard.definition:
{
  "title": "2 · Database Failover Insight",
  "description": "Explain why a redundant database pair failed over, from storage, host, cluster and app signals.",
  "inputs": {},
  "defaults": {},
  "visualizations": {
    "bg_001": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "bg_002": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#16A3B0",
        "strokeColor": "#16A3B0",
        "strokeWidth": 1,
        "rx": 3
      }
    },
    "md_003": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "USE CASE 2 OF 9  ·  SPITAL AARWALD  ·  SAMPLE DATA",
        "fontColor": "#16A3B0",
        "fontSize": "custom",
        "customFontSize": 12
      }
    },
    "md_004": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# Database Failover Insight",
        "fontColor": "#E6EDF3"
      }
    },
    "md_005": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "The standby took over. Splunk lines up storage, host, cluster and app signals to show why.",
        "fontColor": "#9AA4B2",
        "fontSize": "custom",
        "customFontSize": 15
      }
    },
    "bg_006": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#11161D",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 8
      }
    },
    "md_007": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "WHAT WE HEARD",
        "fontColor": "#6E7681",
        "fontSize": "custom",
        "customFontSize": 11
      }
    },
    "md_008": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "*“Redundante Datenbankserver, die aktuell viel zu wenig überwacht werden. Es kann nicht nachvollzogen werden, wieso sich das redundante System aktiviert hat.”*",
        "fontColor": "#9AA4B2",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_009": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_010": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "> majorValue | rangeValue(majorColorConfig)",
        "numberPrecision": 2,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "unit": "%",
        "unitPosition": "after",
        "underLabel": "KIS-DB-01 (SQL Server Always On)",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13,
        "trendColor": "> trendValue | rangeValue(trendColorConfig)"
      },
      "dataSources": {
        "primary": "ds_011"
      },
      "title": "Cluster availability (30 days)",
      "context": {
        "trendColorConfig": [
          {
            "to": -0.0001,
            "value": "#D03B3B"
          },
          {
            "from": -0.0001,
            "to": 0.0001,
            "value": "#9AA4B2"
          },
          {
            "from": 0.0001,
            "value": "#0CA30C"
          }
        ],
        "majorColorConfig": [
          {
            "to": 99.9,
            "value": "#D03B3B"
          },
          {
            "from": 99.9,
            "to": 99.95,
            "value": "#FAB219"
          },
          {
            "from": 99.95,
            "value": "#0CA30C"
          }
        ]
      }
    },
    "bg_012": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_013": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "#E6EDF3",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "underLabel": "2 unplanned · 2 patch windows",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13,
        "trendColor": "> trendValue | rangeValue(trendColorConfig)"
      },
      "dataSources": {
        "primary": "ds_014"
      },
      "title": "Failovers (rolling 90 days)",
      "context": {
        "trendColorConfig": [
          {
            "to": -0.0001,
            "value": "#0CA30C"
          },
          {
            "from": -0.0001,
            "to": 0.0001,
            "value": "#9AA4B2"
          },
          {
            "from": 0.0001,
            "value": "#D03B3B"
          }
        ]
      }
    },
    "bg_015": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_016": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "#E6EDF3",
        "numberPrecision": 1,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "unit": " s",
        "unitPosition": "after",
        "underLabel": "db-sql-01b → db-sql-01a",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13,
        "trendColor": "> trendValue | rangeValue(trendColorConfig)"
      },
      "dataSources": {
        "primary": "ds_017"
      },
      "title": "Replication lag now",
      "context": {
        "trendColorConfig": [
          {
            "to": -0.0001,
            "value": "#0CA30C"
          },
          {
            "from": -0.0001,
            "to": 0.0001,
            "value": "#9AA4B2"
          },
          {
            "from": 0.0001,
            "value": "#D03B3B"
          }
        ]
      }
    },
    "bg_018": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_019": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "#E6EDF3",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "off",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "unit": " min",
        "unitPosition": "after",
        "underLabel": "was ~1 day of log hunting",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13
      },
      "dataSources": {
        "primary": "ds_020"
      },
      "title": "Time to explain a failover"
    },
    "bg_021": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_022": {
      "type": "splunk.line",
      "options": {
        "backgroundColor": "#161B22",
        "legendDisplay": "off",
        "xAxisTitleVisibility": "hide",
        "nullValueDisplay": "connect",
        "lineWidth": 2,
        "seriesColors": [
          "#D95926"
        ],
        "yAxisTitleVisibility": "hide"
      },
      "dataSources": {
        "primary": "ds_023"
      },
      "title": "Storage write latency (ms) — SAN path to db-sql-01a"
    },
    "bg_024": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_025": {
      "type": "splunk.line",
      "options": {
        "backgroundColor": "#161B22",
        "legendDisplay": "right",
        "xAxisTitleVisibility": "hide",
        "nullValueDisplay": "connect",
        "lineWidth": 2,
        "seriesColors": [
          "#D95926",
          "#3987E5"
        ],
        "yAxisTitleVisibility": "hide",
        "yAxisMax": 100
      },
      "dataSources": {
        "primary": "ds_026"
      },
      "title": "CPU % on both nodes"
    },
    "bg_027": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_028": {
      "type": "splunk.column",
      "options": {
        "backgroundColor": "#161B22",
        "legendDisplay": "off",
        "xAxisTitleVisibility": "hide",
        "seriesColors": [
          "#D95926"
        ],
        "stackMode": "stacked",
        "yAxisTitleVisibility": "hide",
        "yAxisMax": 3,
        "yAxisMajorTickInterval": 1
      },
      "dataSources": {
        "primary": "ds_029"
      },
      "title": "Cluster heartbeats missed"
    },
    "bg_030": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_031": {
      "type": "splunk.pie",
      "options": {
        "backgroundColor": "#161B22",
        "showDonutHole": true,
        "labelDisplay": "valuesAndPercentage",
        "legendDisplay": "off",
        "seriesColors": [
          "#3987E5",
          "#D95926",
          "#199E70",
          "#C98500",
          "#D55181",
          "#008300",
          "#9085E9",
          "#E66767"
        ]
      },
      "dataSources": {
        "primary": "ds_032"
      },
      "title": "Failover causes (12 months)"
    },
    "bg_033": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_034": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "#E6EDF3",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "unit": " s",
        "unitPosition": "after",
        "underLabel": "target < 60 s · last 12 failovers",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13,
        "trendColor": "> trendValue | rangeValue(trendColorConfig)"
      },
      "dataSources": {
        "primary": "ds_035"
      },
      "title": "Downtime of this failover",
      "context": {
        "trendColorConfig": [
          {
            "to": -0.0001,
            "value": "#0CA30C"
          },
          {
            "from": -0.0001,
            "to": 0.0001,
            "value": "#9AA4B2"
          },
          {
            "from": 0.0001,
            "value": "#D03B3B"
          }
        ]
      }
    },
    "bg_036": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_037": {
      "type": "splunk.table",
      "options": {
        "backgroundColor": "#161B22",
        "headerVisibility": "fixed",
        "fontSize": "small",
        "columnFormat": {
          "When": {
            "width": 110
          },
          "Layer": {
            "width": 110,
            "rowBackgroundColors": "> table | seriesByName(\"Layer\") | matchValue(c0Bg)",
            "rowColors": "> table | seriesByName(\"Layer\") | matchValue(c0Fg)"
          },
          "System": {
            "width": 170
          },
          "Event": {
            "width": 960
          }
        }
      },
      "dataSources": {
        "primary": "ds_038"
      },
      "title": "What happened — root cause timeline across all layers",
      "context": {
        "c0Bg": [
          {
            "match": "Storage",
            "value": "#3A2518"
          },
          {
            "match": "Host",
            "value": "#3A2E12"
          },
          {
            "match": "Cluster",
            "value": "#3F1D20"
          },
          {
            "match": "App",
            "value": "#1F242C"
          }
        ],
        "c0Fg": [
          {
            "match": "Storage",
            "value": "#F0A070"
          },
          {
            "match": "Host",
            "value": "#E3B341"
          },
          {
            "match": "Cluster",
            "value": "#FF8A80"
          },
          {
            "match": "App",
            "value": "#9AA4B2"
          }
        ]
      }
    },
    "bg_039": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "md_040": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "DATA SOURCES NEEDED IN SPLUNK",
        "fontColor": "#16A3B0",
        "fontSize": "custom",
        "customFontSize": 12
      }
    },
    "bg_041": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_042": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "Database & cluster logs",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_043": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_044": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "OS metrics (Windows / Linux)",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_045": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_046": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "Storage / SAN logs",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_047": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_048": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "Application logs & health checks",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    }
  },
  "dataSources": {
    "ds_011": {
      "type": "ds.search",
      "name": "ds_011",
      "options": {
        "query": "| makeresults format=csv data=\"ago,pct\n29,100.0\n28,100.0\n27,100.0\n26,100.0\n25,100.0\n24,100.0\n23,99.91\n22,100.0\n21,100.0\n20,100.0\n19,100.0\n18,100.0\n17,100.0\n16,100.0\n15,100.0\n14,100.0\n13,100.0\n12,99.95\n11,100.0\n10,100.0\n9,100.0\n8,100.0\n7,100.0\n6,100.0\n5,100.0\n4,100.0\n3,100.0\n2,100.0\n1,100.0\n0,99.97\"\n| eval _time=relative_time(now(), \"@d\") - ago*86400\n| sort 0 _time\n| table _time pct",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_014": {
      "type": "ds.search",
      "name": "ds_014",
      "options": {
        "query": "| makeresults format=csv data=\"ago,n\n12,3\n11,3\n10,3\n9,4\n8,4\n7,4\n6,3\n5,3\n4,3\n3,3\n2,3\n1,3\n0,4\"\n| eval _time=relative_time(now(), \"@d\") - ago*604800\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_017": {
      "type": "ds.search",
      "name": "ds_017",
      "options": {
        "query": "| makeresults format=csv data=\"ago,lag\n59,0.68\n58,0.68\n57,0.32\n56,0.33\n55,0.63\n54,0.59\n53,0.57\n52,0.42\n51,0.54\n50,0.54\n49,0.53\n48,0.36\n47,0.47\n46,0.46\n45,0.59\n44,0.7\n43,0.68\n42,0.52\n41,0.48\n40,0.41\n39,0.31\n38,0.31\n37,0.49\n36,0.43\n35,0.45\n34,0.66\n33,0.51\n32,0.52\n31,0.39\n30,0.31\n29,0.43\n28,0.35\n27,0.5\n26,0.7\n25,0.57\n24,0.37\n23,0.66\n22,0.62\n21,0.59\n20,0.66\n19,9.05\n18,9.16\n17,7.42\n16,9.92\n15,9.85\n14,6.64\n13,9.02\n12,8.86\n11,7.85\n10,8.12\n9,7.96\n8,0.67\n7,0.5\n6,0.63\n5,0.44\n4,0.65\n3,0.66\n2,0.48\n1,0.53\n0,0.67\"\n| eval _time=relative_time(now(), \"@m\") - ago*60\n| sort 0 _time\n| table _time lag",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_020": {
      "type": "ds.search",
      "name": "ds_020",
      "options": {
        "query": "| makeresults format=csv data=\"ago,m\n11,1440\n10,960\n9,1200\n8,900\n7,1100\n6,25\n5,14\n4,9\n3,8\n2,7\n1,8\n0,7\"\n| eval _time=relative_time(now(), \"@d\") - ago*604800\n| sort 0 _time\n| table _time m",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_023": {
      "type": "ds.search",
      "name": "ds_023",
      "options": {
        "query": "| makeresults format=csv data=\"ago,db-sql-01a\n44,7\n43,7\n42,5\n41,6\n40,5\n39,6\n38,7\n37,6\n36,6\n35,7\n34,6\n33,5\n32,7\n31,6\n30,4\n29,6\n28,4\n27,5\n26,4\n25,4\n24,4\n23,6\n22,451\n21,358\n20,474\n19,327\n18,493\n17,433\n16,334\n15,518\n14,368\n13,362\n12,5\n11,4\n10,7\n9,4\n8,4\n7,6\n6,6\n5,5\n4,5\n3,4\n2,4\n1,4\n0,4\"\n| eval _time=relative_time(now(), \"@m\") - ago*60\n| sort 0 _time\n| table _time \"db-sql-01a\"",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_026": {
      "type": "ds.search",
      "name": "ds_026",
      "options": {
        "query": "| makeresults format=csv data=\"ago,db-sql-01a (primary),db-sql-01b (standby)\n44,24,11\n43,24,16\n42,28,13\n41,26,13\n40,32,11\n39,30,11\n38,27,13\n37,24,11\n36,29,12\n35,28,16\n34,31,11\n33,28,18\n32,32,11\n31,28,17\n30,33,13\n29,31,14\n28,25,16\n27,25,11\n26,31,13\n25,32,17\n24,31,16\n23,26,16\n22,28,15\n21,33,17\n20,34,11\n19,99,13\n18,99,11\n17,96,11\n16,95,13\n15,95,12\n14,97,14\n13,98,11\n12,10,42\n11,14,46\n10,9,43\n9,9,48\n8,10,48\n7,13,50\n6,11,43\n5,14,45\n4,11,47\n3,9,41\n2,9,45\n1,12,41\n0,9,47\"\n| eval _time=relative_time(now(), \"@m\") - ago*60\n| sort 0 _time\n| table _time \"db-sql-01a (primary)\" \"db-sql-01b (standby)\"",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_029": {
      "type": "ds.search",
      "name": "ds_029",
      "options": {
        "query": "| makeresults format=csv data=\"ago,Missed heartbeats\n44,0\n43,0\n42,0\n41,0\n40,0\n39,0\n38,0\n37,0\n36,0\n35,0\n34,0\n33,0\n32,0\n31,0\n30,0\n29,0\n28,0\n27,0\n26,0\n25,0\n24,0\n23,0\n22,0\n21,0\n20,0\n19,0\n18,0\n17,0\n16,1\n15,1\n14,1\n13,0\n12,0\n11,0\n10,0\n9,0\n8,0\n7,0\n6,0\n5,0\n4,0\n3,0\n2,0\n1,0\n0,0\"\n| eval _time=relative_time(now(), \"@m\") - ago*60\n| sort 0 _time\n| table _time \"Missed heartbeats\"",
        "queryParameters": {
